```javascript
import { appendFileSync } from 'node:fs';
import { randomUUID } from 'node:crypto';
import { definePluginEntry } from 'openclaw/plugin-sdk/plugin-entry';

const record = (event) => appendFileSync(process.env.TOOL_BATCH_PROOF_LOG, JSON.stringify({at:new Date().toISOString(),...event})+'\n');
const result = (details) => ({content:[{type:'text',text:JSON.stringify(details)}],details});
const object = (properties,required=Object.keys(properties)) => ({type:'object',properties,required,additionalProperties:false});
let lookupProof;
let referenceProof;

export default definePluginEntry({
  id:'tool-batch-proof',name:'Tool batch live proof',description:'Temporary synthetic regression proof',
  register(api) {
    record({event:'plugin_registered'});
    api.on('before_message_write',(event)=>{
      const message=event.message;
      if(message?.role==='assistant') {
        const calls=(message.content??[]).filter((part)=>part.type==='toolCall').map((part)=>({toolCallId:part.id,toolName:part.name}));
        if(calls.length) record({event:'assistant_calls_persisted',calls});
      }
    });
    api.on('tool_result_persist',(event)=>{
      const message=event.message;
      const blockFeedback=(message?.content??[]).some((part)=>part.type==='text'&&part.text.includes('BATCH_PROOF_REJECTED'));
      record({event:'tool_result_persisted',toolName:message?.toolName,toolCallId:message?.toolCallId,isError:message?.isError===true,blockFeedback});
    });
    api.on('before_tool_call',(event)=>{
      if (!['lookup_data','read_reference','submit_response'].includes(event.toolName)) return;
      const batch=event.toolBatch;
      const block=event.toolName==='submit_response' && (!batch || batch.membership!=='complete' || batch.calls.length!==1);
      record({event:'before_tool_call',toolName:event.toolName,toolCallId:event.toolCallId,toolBatch:batch,decision:block?'block':'allow'});
      if(block) return {block:true,blockReason:'BATCH_PROOF_REJECTED: submit_response must be the only call in a complete assistant response. Consume lookup_data and read_reference results, then retry submit_response alone with their exact proof tokens and sum.'};
    });
    api.registerTool({
      name:'lookup_data',label:'Lookup data',catalogMode:'direct-only',
      description:'Retrieve synthetic lookup value and a fresh proof token. No arguments.',parameters:object({}),
      async execute(id) {
        lookupProof=randomUUID();
        record({event:'tool_executed',toolName:'lookup_data',toolCallId:id});
        return result({lookup_value:17,lookup_proof:lookupProof});
      },
    });
    api.registerTool({
      name:'read_reference',label:'Read reference',catalogMode:'direct-only',
      description:'Retrieve synthetic reference value and a fresh proof token. No arguments.',parameters:object({}),
      async execute(id) {
        referenceProof=randomUUID();
        record({event:'tool_executed',toolName:'read_reference',toolCallId:id});
        return result({reference_value:25,reference_proof:referenceProof});
      },
    });
    api.registerTool({
      name:'submit_response',label:'Submit synthetic response',catalogMode:'direct-only',
      description:'Submit a synthetic final result. Supply both fresh tokens from lookup_data/read_reference and their value sum. Host policy requires this to be the sole call in a complete response. No external delivery occurs.',
      parameters:object({lookup_proof:{type:'string'},reference_proof:{type:'string'},sum:{type:'number'}}),
      async execute(id,params) {
        const verified=Boolean(lookupProof && referenceProof && params.lookup_proof===lookupProof && params.reference_proof===referenceProof && params.sum===42);
        record({event:'tool_executed',toolName:'submit_response',toolCallId:id,verifiedBothSiblingResults:verified});
        if(!verified) throw new Error('BATCH_PROOF_INVALID: both exact fresh sibling tokens and sum 42 required.');
        return result({status:'BATCH_PROOF_ACCEPTED',verified_both_sibling_results:true,sum:42});
      },
    });
  },
});
