const meta=JSON.parse(readFileSync(path.join(root,'metadata.json'),'utf8'));
assert.equal(meta.head,'23c5ede36f5164b316dc24d76b80ec30412a2119');
assert.equal(meta.exitCode,0);
const hooks=events.filter(e=>e.event==='before_tool_call');
const mixed=hooks.find(e=>e.toolName==='submit_response'&&e.decision==='block'&&e.toolBatch?.membership==='complete'&&e.toolBatch.calls.length===3);
assert.ok(mixed,'Missing selectively rejected complete mixed batch');
assert.deepEqual(mixed.toolBatch.calls.map(c=>c.toolName).sort(),['lookup_data','read_reference','submit_response']);
const first=hooks.filter(e=>e.toolBatch?.id===mixed.toolBatch.id);
assert.equal(first.length,3);
for(const name of ['lookup_data','read_reference']) {
