  assert.ok(events.some(e=>e.event==='tool_result_persisted'&&e.toolCallId===hook.toolCallId&&!e.isError));
}
assert.ok(!events.some(e=>e.event==='tool_executed'&&e.toolCallId===mixed.toolCallId),'Rejected submission executed');
assert.ok(events.some(e=>e.event==='tool_result_persisted'&&e.toolCallId===mixed.toolCallId&&e.isError&&e.blockFeedback),'Block feedback missing from transcript');
const solo=hooks.find(e=>e.toolName==='submit_response'&&e.decision==='allow'&&e.toolBatch?.membership==='complete'&&e.toolBatch.calls.length===1);
assert.ok(solo,'Missing subsequent standalone submission');
assert.notEqual(solo.toolBatch.id,mixed.toolBatch.id);
const accepted=events.find(e=>e.event==='tool_executed'&&e.toolCallId===solo.toolCallId&&e.verifiedBothSiblingResults===true);
assert.ok(accepted,'Model did not return both fresh sibling result tokens');
assert.ok(events.indexOf(accepted)>events.indexOf(mixed));
const stdout=readFileSync(path.join(root,'stdout.txt'),'utf8');
const envelope=JSON.parse(stdout.slice(stdout.indexOf('{')));
assert.equal(envelope.ok,true);
assert.equal(envelope.final.trim(),'BATCH_PROOF_DONE');
const result={status:'PASS',head:meta.head,model:'deepseek/deepseek-flash',mixedBatchId:mixed.toolBatch.id,standaloneBatchId:solo.toolBatch.id,selectiveBlock:true,siblingsExecuted:true,blockFeedbackPersisted:true,bothFreshSiblingResultsVerified:true,standaloneAccepted:true,exitCode:meta.exitCode,usage:envelope.usage,costUsd:envelope.costUsd,assistantTurns:envelope.assistantTurns,streamingMembershipObserved:hooks.some(e=>e.toolBatch?.membership==='streaming')};
writeFileSync(path.join(root,'assertions.json'),JSON.stringify(result,null,2)+'\n');
