The initial driver returned `NO_REPLY` for repair and incorrectly equated its contextKey with runId. The corrected driver below uses a visible synthetic repair response and actual observer identity. That change occurs after the Cron occurrence and cannot synthesize its watchdog outcome. No product code changed between candidate attempts.

```javascript
import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import os from 'node:os';
import path from 'node:path';
import { createServer } from 'node:http';
import { json } from 'node:stream/consumers';
import { setTimeout as sleep } from 'node:timers/promises';
import { fileURLToPath, pathToFileURL } from 'node:url';
import { createHash, randomUUID } from 'node:crypto';
import { DatabaseSync } from 'node:sqlite';
import { execFileSync } from 'node:child_process';
import { zstdDecompressSync } from 'node:zlib';

// The supervisor supplies source/build identity and owns sequential arm execution.
// This script never builds, changes Git, changes watchdog clocks, or edits product files.
const repo = process.env.QA_WATCHDOG_PROOF_REPO;
const base = process.env.QA_WATCHDOG_PROOF_BASE;
const arm = process.env.QA_WATCHDOG_PROOF_ARM ?? process.env.QA_WATCHDOG_ARM;
const expected = process.env.QA_EXPECTED_SOURCE_DIFF_SHA256;
const out = process.env.QA_WATCHDOG_PROOF_OUT;
const preflightOnly = process.env.QA_WATCHDOG_PREFLIGHT_ONLY === '1';
const routes = process.env.QA_WATCHDOG_PROOF_ROUTES ?? 'all';
assert(['all', 'announce'].includes(routes), 'Supported route selections: all|announce');
assert(repo && path.isAbsolute(repo), 'Explicit absolute QA_WATCHDOG_PROOF_REPO required');
assert(out && path.isAbsolute(out), 'Explicit per-attempt QA_WATCHDOG_PROOF_OUT required');
assert(/^[0-9a-f]{40}$/.test(base ?? ''), 'Explicit immutable upstream base required');
assert(['baseline', 'candidate'].includes(arm), 'Explicit baseline|candidate arm required');
assert(/^[0-9a-f]{64}$/.test(expected ?? ''), 'Expected working-source diff SHA-256 required');
const sha = value => createHash('sha256').update(value).digest('hex');
const git = (...args) => execFileSync('git', args, { cwd: repo, env: { ...process.env, GIT_OPTIONAL_LOCKS: '0' }, maxBuffer: 32 * 1024 * 1024 });
const workingDiff = () => git('diff', '--binary', base);
const originalDiff = workingDiff();
assert.equal(sha(originalDiff), expected, 'Working source differs from supervisor freeze');
if (arm === 'baseline') assert.equal(originalDiff.length, 0, 'Baseline must be complete upstream working source');
const pin = {
  base, arm, head: git('rev-parse', 'HEAD').toString().trim(), workingDiffSha256: expected,
  // HEAD/index may retain the unpublished merge while baseline bytes are materialized.
  sourceIdentity: 'complete tracked working source compared directly with immutable base',
  files: {}, buildFiles: {}, driverSha256: sha(await fs.readFile(fileURLToPath(import.meta.url))),
};
