async function guarded(promise) {
  if (abort.signal.aborted) {
    // An argument promise may already have been started by its owner. Observe
    // its rejection; the registered Gateway owner joins it during cleanup.
    void Promise.resolve(promise).catch(() => {});
    throw abort.signal.reason;
