    const db = new DatabaseSync(file, { readOnly: true });
    try {
      if (!db.prepare("SELECT 1 FROM sqlite_master WHERE type='table' AND name='cron_jobs'").get()) continue;
      const rows = db.prepare('SELECT job_json, state_json FROM cron_jobs WHERE job_id = ?').all(jobId);
      if (!rows.length) continue;
      assert.equal(rows.length, 1);
      return { ...JSON.parse(rows[0].job_json), state: JSON.parse(rows[0].state_json) };
    } finally { db.close(); }
  }
  throw new Error(`Fixture-owned ${jobId} missing from canonical cron store`);
}
