    item.preflight = { operatorSourceCaptured: true, operatorSourceSha256: item.sourceHash, executionOwnerBound: true,
      humanOwnerProfilePresent: Boolean(stored.ownerProfileId), sourceForged: false };
    const obs = observations();
    assert(obs.some(event => event.kind === 'llm_input' && event.runId === item.creatorRunId));
    assert(obs.some(event => event.kind === 'model_call_started' && event.runId === item.creatorRunId));
  }
  assert.equal(new Set(cases.filter(item => item.sessionKey).map(item => item.sessionKey)).size, cases.filter(item => !item.direct).length);
  phase = 'run';
  const ordinary = cases.find(item => item.ordinary);
  await rpc('cron.run', { id: ordinary.jobId, mode: 'force' });
  ordinary.entry = await waitForFinished(ordinary, 90_000);
  assert.equal(ordinary.entry.status, 'ok', 'Ordinary named schedule must succeed on both arms');
  assert.equal(ordinary.entry.delivered, true, 'Same-conversation committed result must satisfy delivery');
  const ordinaryStored = await storedJob(ordinary.jobId);
  assert(!ordinaryStored.state.failureAlertIncident, 'Ordinary success must not create failure incident');
  const ordinaryHistory = await rpc('chat.history', { sessionKey: ordinary.sessionKey, limit: 50 });
  const ordinarySerialized = JSON.stringify(ordinaryHistory.messages ?? []);
  assert(ordinarySerialized.includes('QA_ORDINARY_RESULT_COMMITTED'), 'Ordinary result missing from public conversation history');
  result.ordinary = { status: ordinary.entry.status, delivered: ordinary.entry.delivered, completionStatus: ordinary.entry.completionStatus ?? null,
    operatorSourceRetained: sha(JSON.stringify(ordinaryStored.operatorSource)) === ordinary.sourceHash, failureIncident: false };
  assert(result.ordinary.operatorSourceRetained);
  assert.equal(busState.getSnapshot().messages.filter(message => message.direction === 'outbound').length, 0, 'Same-conversation success must not send a QA failure alert');
  if (preflightOnly) {
    result.preflightPassed = true;
  } else {
    const started = Date.now();
    for (const item of quietCases) await rpc('cron.run', { id: item.jobId, mode: 'force' });
    let heartbeatAt = 0;
    while (Date.now() - started < 1_080_000) {
      for (const item of quietCases) if (!item.entry) item.entry = await finishedEntry(item);
      if (quietCases.every(item => item.entry)) break;
      if (Date.now() - heartbeatAt > 30_000) {
        log({ phase: 'natural-watchdog-wait', elapsedMs: Date.now() - started,
          settled: quietCases.filter(item => item.entry).map(item => item.label),
          toolsStarted: observations().filter(event => event.kind === 'tool_started').length });
        heartbeatAt = Date.now();
      }
      await pause(1000);
    }
    assert(quietCases.every(item => item.entry), 'All genuine watchdog occurrences must settle');
    const settleUntil = Date.now() + 45_000;
    while (Date.now() < settleUntil) {
      const stored = await storedJob(cases.find(item => item.label === 'announce').jobId);
      if (arm === 'baseline' || stored.state.failureAlertIncident?.repair?.settledAtMs !== undefined) break;
      await pause(250);
    }
    const obs = observations();
    result.observations = obs;
    for (const item of quietCases) {
      const stored = await storedJob(item.jobId);
      const inputs = obs.filter(event => event.kind === 'llm_input' && event.trigger === 'cron' && !event.repairBrief && event.markers?.includes(item.marker));
      assert.equal(inputs.length, 1, 'Exactly one admitted model turn per occurrence');
      const runId = inputs[0].runId;
      const starts = obs.filter(event => event.kind === 'tool_started' && event.runId === runId);
      const stops = obs.filter(event => event.kind === 'tool_aborted' && event.runId === runId);
      assert.equal(starts.length, 1); assert.equal(stops.length, 1);
      assert.equal(stops[0].code, 'OPENCLAW_SESSION_WATCHDOG');
      const quietElapsedMs = stops[0].at - starts[0].at;
      assert(quietElapsedMs >= 899_000, 'Quiet-tool stop occurred before the genuine 15-minute boundary');
      const cronCalls = obs.filter(event => event.kind === 'model_call_started' && event.runId === runId);
      const cronWire = requestEvidence.filter(event => event.label === item.label && event.role === 'cron-occurrence');
      assert.equal(cronCalls.length, 1); assert.equal(cronWire.length, 1);
      const row = { label: item.label, jobId: item.jobId, runId, quietElapsedMs,
        status: item.entry.status, error: item.entry.error ?? null, diagnosticsSummary: item.entry.diagnostics?.summary ?? null,
        enabled: stored.enabled, nextRunInFuture: stored.state.nextRunAtMs > Date.now(),
        operatorSourceRetained: item.direct ? null : sha(JSON.stringify(stored.operatorSource)) === item.sourceHash,
        cronModelCalls: cronCalls.length, cronWireRequests: cronWire.length,
        repairWireRequests: requestEvidence.filter(event => event.label === item.label && event.role === 'failure-repair').length,
        state: stateEvidence(stored) };
      result.cases.push(row); log({ phase: 'observed-product-result', ...row });
      if (arm === 'baseline') {
        assert(!fixedCauses.includes(row.error), 'Baseline unexpectedly contains candidate watchdog cause; requalify before claiming red');
        continue;
      }
      assert.equal(row.status, 'error'); assert(fixedCauses.includes(row.error));
      assert.equal(row.diagnosticsSummary, row.error, 'Durable run diagnostics must retain fixed cause');
      assert(row.enabled && row.nextRunInFuture);
      if (!item.direct) assert(row.operatorSourceRetained);
      if (item.label === 'announce') {
        assert.equal(row.repairWireRequests, 1); assert(row.state.repair?.settledAtMs !== undefined);
        assert.equal(row.state.lastFailureNotificationDeliveryStatus, 'not-requested');
        // contextKey identifies custody; the actual dispatched turn owns a fresh run ID.
        const repairInputs = obs.filter(event => event.kind === 'llm_input' && event.repairBrief && event.repairJobId === item.jobId);
        assert.equal(repairInputs.length, 1, 'Exactly one admitted repair turn for this occurrence');
        const repairRunId = repairInputs[0].runId;
        assert(repairRunId && repairRunId !== runId);
        assert.equal(obs.filter(event => event.kind === 'model_call_started' && event.runId === repairRunId).length, 1);
        assert(!obs.some(event => event.kind === 'tool_started' && event.runId === repairRunId));
      } else if (item.direct) {
        assert.equal(row.repairWireRequests, 0); assert.equal(row.state.repair, null);
        assert.equal(row.state.executionOwnerSessionPresent, false);
        const alerts = busState.getSnapshot().messages.filter(message => message.direction === 'outbound' && (message.text ?? '').includes(`Cause: ${row.error}`) && message.text.includes(recoveryInstruction));
        assert.equal(alerts.length, 1); assert.equal(row.state.lastFailureNotificationDeliveryStatus, 'delivered');
      } else {
        assert.equal(row.repairWireRequests, 0); assert.equal(row.state.repair, null);
        const delivered = webhookReceipts.filter(receipt => receipt.jobId === item.jobId);
        assert.equal(delivered.length, 1); assert.equal(typeof delivered[0].runAtMs, 'number');
        assert(delivered[0].message.includes(`Last error: ${row.error}`));
        assert.equal(row.state.lastFailureNotificationDeliveryStatus, 'delivered');
      }
    }
    if (arm === 'candidate') assert.equal(busState.getSnapshot().messages.filter(message => message.direction === 'outbound').length, cases.some(item => item.direct) ? 1 : 0);
    settledProof = true;
  }
} catch (error) {
  result.failure = { name: error?.name ?? 'Error', message: String(error?.message ?? error).split('\nGateway logs:')[0].replace(/https?:\/\/[^\s)]+/g, '<endpoint>') };
  log({ phase: 'failure', ...result.failure });
  // QA owner exposes redacted logs; retain them locally for setup diagnosis before
  // successful teardown removes its owned state. Never print them in chat/public.
  if (gateway) {
    try { await fs.writeFile(path.join(out, 'gateway-failure.redacted.log'), gateway.logs()); }
    catch (logError) { result.failureLogError = String(logError?.message ?? logError); }
  }
  process.exitCode = 1;
} finally {
  result.preflight = cases.map(item => ({ label: item.label, jobId: item.jobId, ...item.preflight }));
  result.observations ??= observations();
  result.qaOutbound = busState?.getSnapshot().messages.filter(message => message.direction === 'outbound').map(message => ({ text: message.text ?? '' })) ?? [];
  for (const [label, cleanup] of cleanups) {
    try { await cleanup(); }
    catch (error) { result.cleanupErrors.push({ label, name: error?.name ?? 'Error', message: String(error?.message ?? error).replace(/https?:\/\/[^\s)]+/g, '<endpoint>') }); process.exitCode = 1; }
  }
  try { result.trackedWorkingSourceUnchanged = sha(workingDiff()) === expected; assert(result.trackedWorkingSourceUnchanged); }
  catch { result.trackedWorkingSourceUnchanged = false; process.exitCode = 1; }
  result.success = !result.failure && result.cleanupErrors.length === 0 && result.trackedWorkingSourceUnchanged
    && result.gatewayStopped === true && result.gatewayTempRootRemoved === true
    && (preflightOnly ? result.preflightPassed === true : settledProof);
  if (!result.success) process.exitCode = 1;
  result.completedAt = new Date().toISOString();
  process.removeListener('SIGTERM', onTerm); process.removeListener('SIGINT', onInt);
  await fs.writeFile(receiptPath, JSON.stringify(result, null, 2) + '\n');
  log({ phase: 'completion', arm, preflightOnly, success: result.success, cleanupErrors: result.cleanupErrors.length,
    gatewayStopped: result.gatewayStopped === true, sourceUnchanged: result.trackedWorkingSourceUnchanged });
}

