<details><summary>Throwaway server (vendor-format-mcp.mjs)</summary>

```js
import { createInterface } from "node:readline";

const tools = [
  {
    name: "compute_route",
    description: "Returns a route with a Google-style duration.",
    inputSchema: {
      type: "object",
      properties: { origin: { type: "string" }, destination: { type: "string" } },
      required: ["origin", "destination"],
    },
    outputSchema: {
      type: "object",
      properties: {
        duration: { type: "string", format: "google-duration" },
        stops: { type: "integer", format: "uint" },
      },
      required: ["duration", "stops"],
    },
  },
  {
    name: "lookup_contact",
    description: "Returns a contact with a validated email.",
    inputSchema: { type: "object", properties: { id: { type: "string" } }, required: ["id"] },
    outputSchema: {
      type: "object",
      properties: { email: { type: "string", format: "email" } },
      required: ["email"],
    },
  },
];

const send = (message) => process.stdout.write(`${JSON.stringify({ jsonrpc: "2.0", ...message })}\n`);

createInterface({ input: process.stdin }).on("line", (line) => {
  if (!line.trim()) return;
  const { id, method, params } = JSON.parse(line);
  if (id === undefined) return;
  if (method === "initialize") {
    send({
      id,
      result: {
        protocolVersion: params.protocolVersion,
        capabilities: { tools: {} },
        serverInfo: { name: "vendor-format-mcp", version: "0.0.1" },
      },
    });
  } else if (method === "tools/list") {
    send({ id, result: { tools } });
  } else if (method === "tools/call") {
    const structuredContent =
      params.name === "compute_route"
        ? { duration: "3600s", stops: 2 }
        : { email: params.arguments?.id === "bad" ? "not-an-email" : "ada@example.com" };
    send({ id, result: { content: [{ type: "text", text: JSON.stringify(structuredContent) }], structuredContent } });
  } else {
    send({ id, error: { code: -32601, message: `Method not found: ${method}` } });
  }
});
```
